import * as z from 'zod'

import {buildEntrySchemaFor} from '@github-ui/swp-core/schemas/contentful/entry'
import {buildPageSchemaForTemplate} from '@github-ui/swp-core/schemas/contentful/contentTypes/containerPage'
import {PrimerComponentCtaBannerSchema} from '@github-ui/swp-core/schemas/contentful/contentTypes/primerComponentCtaBanner'
import {PrimerComponentHeroSchema} from '@github-ui/swp-core/schemas/contentful/contentTypes/primerComponentHero'
import {PrimerComponentSubnavSchema} from '@github-ui/swp-core/schemas/contentful/contentTypes/primerComponentSubnav'
import {safeOptional} from '@github-ui/swp-core/schemas/safe-optional'

const GenericSectionContentItemSchema = z.union([PrimerComponentHeroSchema, PrimerComponentCtaBannerSchema])

const GenericSectionContentSchema = z.lazy(() =>
  z
    .array(z.unknown())
    .transform(items => items.filter(item => GenericSectionContentItemSchema.safeParse(item).success))
    .pipe(z.array(GenericSectionContentItemSchema)),
)

const GenericSectionSchema = buildEntrySchemaFor('genericSection', {
  fields: z.lazy(() =>
    z.object({
      id: z.string().optional(),
      content: GenericSectionContentSchema,
    }),
  ),
})

export type GenericSection = z.infer<typeof GenericSectionSchema>

const TemplateBrandSchema = buildEntrySchemaFor('templateBrand', {
  fields: z.lazy(() =>
    z.object({
      subnav: safeOptional(PrimerComponentSubnavSchema),
      content: z.array(GenericSectionSchema),
    }),
  ),
})

const PublicMonitoringPageSchema = buildPageSchemaForTemplate(TemplateBrandSchema)

const EntryCollection = z.lazy(() => z.array(z.looseObject({})).min(1))

export const toPublicMonitoringPage = (contentfulPayload: unknown) => {
  const page = EntryCollection.parse(contentfulPayload).at(0)
  return safeOptional(PublicMonitoringPageSchema).parse(page)
}
